// Comparator - Flag images that contain "at least" or "fewer than" the configured number of faces. Defaults to at_least.
type Comparator string

const (
	ComparatorAtLeast   Comparator = "at_least"
	ComparatorFewerThan Comparator = "fewer_than"
)

func (e Comparator) ToPointer() *Comparator {
	return &e
}
func (e *Comparator) UnmarshalJSON(data []byte) error {
	var v string
	if err := json.Unmarshal(data, &v); err != nil {
		return err
	}
	switch v {
	case "at_least":
		fallthrough
	case "fewer_than":
		*e = Comparator(v)
		return nil
	default:
		return fmt.Errorf("invalid value for Comparator: %v", v)
	}
}

